function formatRelativeTime(iso: string): string {
  const then = new Date(iso);
  const now = new Date();
  const diffMin = (now.getTime() - then.getTime()) / 60000;

  if (diffMin < 60) {
    return `${Math.floor(diffMin)}m ago`;
  }
  return "a while ago";
}
```

